+import { feltdbRefusal, HostError } from "./collections.js";

 export const TENANCY_COLLECTIONS = ["_feltkit_tenants", "_feltkit_memberships", "_feltkit_invitations"] as const;

@@ -31,6 +31,27 @@ export function tenancyCollection(name: unknown): string {

 type Write = { collection: string; id: string; kind: "create" | "replace" | "delete"; value?: Record<string, unknown> };

+/**
+ * A FeltDB failure of a tenancy@1 commit, mapped as collections.ts commitError does: only a failed
+ * precondition is a CONFLICT in which nothing was written; an unconfirmed commit may have landed.
+ */
+function tenancyCommitError(error: unknown): unknown {
+  if (error instanceof HostError) return error;
+  const code = (error as { code?: unknown } | null)?.code;
+  const details = { feltdbCode: code };
+  if (code === FeltDBErrorCode.PRECONDITION_FAILED) {
+    return new HostError("CONFLICT", `The membership change conflicted with a concurrent one; nothing was written. (${(error as Error).message})`, { details, cause: error });
+  }
+  if (code === FeltDBErrorCode.COMMIT_OUTCOME_UNKNOWN || code === FeltDBErrorCode.DURABILITY_FAILURE) {
+    return new HostError("OUTCOME_UNKNOWN", `FeltDB could not confirm the membership change (${String(code)}); it may or may not have been written.`, {
+      details,
+      hint: "Read the tenant and membership records before acting again; retrying a provision may create a second organization.",
+      cause: error
+    });
+  }
+  return feltdbRefusal(error) ?? error;
+}
+
 /** One tenancy@1 operation's reads and writes over the host's FeltDB. */
 export class TenancyTransaction {
   readonly #db: StateFirstDB;
@@ -76,7 +97,7 @@ export class TenancyTransaction {
     try {
       await this.#db.transaction({ operations } as never);
     } catch (error) {
-      throw new HostError("CONFLICT", `The membership change conflicted with a concurrent one; nothing was written. (${(error as Error).message})`);
+      throw tenancyCommitError(error);
     }
   }
